#include <stdio.h>

long long modpow(long long a, long long e, long long mod) {
    long long res = 1;
    while (e) {
        if (e & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        e >>= 1;
    }
    return res;
}

int main() {
    long long N, K, M;
    scanf("%lld %lld %lld", &N, &K, &M);

    if (K % 2 == 0) {
        // If K is even, numbers never change parity.
        // Each residue class modulo 2 is independent.
        // Within each class, we can think of chain length ~ N/2 + 1 choices.
        long long half = N / 2;
        long long cnt_even = half + 1; // numbers 0,2,4,... up to N if N even else N-1
        long long cnt_odd = half + (N % 2); // numbers 1,3,5,... up to N if N odd
        long long ans = (modpow(2, cnt_even, M) * modpow(2, cnt_odd, M)) % M;
        printf("%lld\n", ans);
    } else {
        // K is odd. gcd(2,K)=1, so all numbers are connected.
        // The number of possible sets = 2^(N+1) mod M
        printf("%lld\n", modpow(2, N + 1, M));
    }

    return 0;
}

