    // For each residue r in [1..K], count elements in [1..N]: m = (N - r)/K + 1
    // Number of reachable states for class of size m = m+1
    // Total = product of (m_r + 1) for r=1..K, mod M

    long long ans = 1;
    for (long long r = 1; r <= K; r++) {
        long long m = (N - r) / K + 1;
        ans = (ans * ((m + 1) % M)) % M;
    }

