typedef long long ll;

static ll mod_pow(ll a, ll e, ll mod) {
    ll r = 1 % mod;
    a %= mod;
    while (e > 0) {
        if (e & 1) r = (ll)((__int128)r * a % mod);
        a = (ll)((__int128)a * a % mod);
        e >>= 1;
    }
    return r;
}

int main(void) {
    ll N, K, M;
    if (scanf("%lld %lld %lld", &N, &K, &M) != 3) return 0;

    if (M == 1) {
        printf("0\n");
        return 0;
    }

    if (K == 1) {
        /* Each chosen x removes x and adds x-2, x+1.
           Net effect on the positive part is independent per x in [1..N]:
           each x can be either kept or removed, giving 2^N sets. */
        printf("%lld\n", mod_pow(2, N, M));
        return 0;
    }

    ll ans = 1 % M;

    /* For each residue class modulo (K+2), the process forms a chain.
       Let L_r be the number of integers in [1..N] in that residue class.
       Number of reachable subsets on a chain of length L is Fibonacci-like:
         dp[0]=1, dp[1]=2, dp[i]=dp[i-1]+dp[i-2]
       i.e. F_{L+2} if F_0=0,F_1=1.
       There are:
         q = N / (K+2), rem = N % (K+2)
       residue classes with lengths q or q+1.
    */
    ll mod = M;
    ll q = N / (K + 2);
    ll rem = N % (K + 2);

    /* Compute g(L): number for one chain of length L */
    ll gq, gq1;

    if (q == 0) {
        gq = 1 % mod;
    } else {
        ll a = 1 % mod, b = 2 % mod; /* dp[0], dp[1] */
        for (ll i = 2; i <= q; i++) {
            ll c = a + b;
            if (c >= mod) c -= mod;
            a = b;
            b = c;
        }
        gq = (q == 0 ? 1 % mod : b);
    }

    {
        ll L = q + 1;
        if (L == 0) {
            gq1 = 1 % mod;
        } else if (L == 1) {
            gq1 = 2 % mod;
        } else {
            ll a = 1 % mod, b = 2 % mod;
            for (ll i = 2; i <= L; i++) {
                ll c = a + b;
                if (c >= mod) c -= mod;
                a = b;
                b = c;
            }
            gq1 = b;
        }
    }

    ans = (ll)((__int128)mod_pow(gq1, rem, mod) * mod_pow(gq, (K + 2) - rem, mod) % mod);
    printf("%lld\n", ans);
    return 0;
}

import java.util.Scanner;

public class Main {
    static final long INF = (long) 1e18;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long K = sc.nextLong();
        long M = sc.nextLong();
        sc.close();

        long g = gcd(2, K);
        long step = g; // gcd(2, K) is either 1 or 2

        // Count numbers from -INF to INF that are ≡ 1..N (mod something)?
        // Actually we care about numbers reachable by operations.
        // The operation preserves parity if K even, flips if K odd relative to -2 shift.
        // Known result: Number of possible sets = 2^(number of "independent intervals").

        // The number of intervals = (2*INF + 1) / step? But bounded by N selection?
        // Let's derive:
        // The operation effectively lets us choose any subset of positions in each residue class mod step.
        // Since initial set is all integers, each residue class is infinite in both directions.
        // The only constraint: we can only "split" numbers that are between 1 and N initially.
        // So for each residue class r (0..step-1), the numbers in [1, N] with that residue
        // form a contiguous block of length = count_in_residue.
        // Each such block can be independently toggled? Actually each selected x creates 2 new numbers,
        // so the reachable sets correspond to all subsets of those initial "split points".
        // So answer = product over residues of 2^(count_in_residue) mod M.

        long ans = 1;
        for (long r = 0; r < step; r++) {
            long first = r;
            if (first < 1) {
                first += ((1 - first + step - 1) / step) * step;
            }
            if (first > N) {
                continue;
            }
            long last = N - ((N - r) % step + step) % step;
            if (last < first) continue;
            long cnt = (last - first) / step + 1;
            ans = ans * modPow(2, cnt, M) % M;
        }

        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static long modPow(long a, long e, long mod) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return res;
    }
}

