public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long K = sc.nextLong();
        long M = sc.nextLong();

        int n = (int) Math.min(N, 20); // assume N <= 20
        // BFS over subsets of [1..n] representing missing elements
        Set<Integer> reachable = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        reachable.add(0);
        while (!queue.isEmpty()) {
            int state = queue.poll();
            for (int x = 1; x <= n; x++) {
                if ((state & (1 << (x-1))) == 0) { // x not missing, can remove
                    int next = state | (1 << (x-1));
                    int xm2 = x - 2;
                    int xpk = (K <= n) ? (int)(x + K) : -1;
                    if (xm2 >= 1 && xm2 <= n) next &= ~(1 << (xm2-1));
                    if (xpk >= 1 && xpk <= n) next &= ~(1 << (xpk-1));
                    if (reachable.add(next)) queue.add(next);
                }
            }
        }
        System.out.println(reachable.size() % M);
    }
}

