public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long N = fs.nextLong();
        long K = fs.nextLong();
        long M = fs.nextLong();

        if (M == 1) {
            System.out.println(0);
            return;
        }

        // Key observation:
        // For each chosen x in [1..N], operation replaces x by x-2 and x+K.
        // This preserves value modulo g = gcd(2, K).
        // Since gcd(2, K) is either 1 or 2:
        //
        // If K is odd, g = 1. All positive integers form one chain under moves by -2 and +K,
        // and every operation is always applicable independently in the poset induced by
        // reachability. The number of reachable final sets equals Fibonacci-like count on [1..N]:
        // dp[i] = dp[i-1] + dp[i-(K+2)].
        //
        // More concretely, choosing x forbids choosing x+2 and x-K in a canonical representation,
        // so reachable sets correspond to independent sets on a path-like graph by residue classes mod 2.
        //
        // For even K, parity is preserved, and odd/even parts are independent.
        // Each parity class gives the same recurrence on its own chain length.
        //
        // Let f(L) be:
        // f[i] = f[i-1] + f[i-1-K/2] on parity-compressed chain for even K,
        // and for odd K directly on length N with gap K+1 over alternating positions.
        //
        // This simplifies to:
        // - If K odd: answer = F(N), where
        //      F(0..K+1 base) via recurrence a[n]=a[n-1]+a[n-K-2], a[0]=1.
        // - If K even: split counts by parity lengths Lo=(N+1)/2, Le=N/2,
        //      G(n)=G(n-1)+G(n-1-K/2), G(0)=1,
        //      answer = G(Lo)*G(Le).
        //
        // We compute these linear recurrences by straightforward DP in O(N), which is fine only if N small.
        // But N can be large, so we use the fact that the recurrence has small order <= K+2 potentially large too.
        // However constraints are not stated; to remain robust for large N and K, derive closed form:
        //
        // Actually because all numbers outside [1..N] are already on board, adding them changes nothing.
        // Thus effect of choosing x only matters when x-2 or x+K lies inside [1..N] and has been erased.
        // This means operations only matter on dependency graph with edges x -> x+2 and x -> x-K.
        // A set of erased numbers S is feasible iff whenever x in S and predecessor in [1..N], predecessor also in S.
        // Hence S is an order ideal in poset generated by x < x+2 and x < x-K.
        //
        // This poset structure yields:
        // - If K odd: total order 1, K+1, K-1, ... equivalent to a chain of size N, so number = N+1.
        // - If K even: two independent chains by parity, so answer = (Lo+1)(Le+1).
        //
        // Therefore:
        long ans;
        if ((K & 1L) == 1L) {
            ans = (N + 1) % M;
        } else {
            long lo = (N + 1) / 2;
            long le = N / 2;
            ans = ((lo + 1) % M) * ((le + 1) % M) % M;
        }

        System.out.println(ans % M);
    }
}

