using int64 = long long;
using i128 = __int128_t;

static long long mod_pow(long long a, long long e, long long mod) {
    long long r = 1 % mod;
    a %= mod;
    while (e > 0) {
        if (e & 1) r = (i128)r * a % mod;
        a = (i128)a * a % mod;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, K, M;
    cin >> N >> K >> M;

    if (M == 1) {
        cout << 0 << '\n';
        return 0;
    }

    // If K is even, parity is preserved by both moves (-2 and +K),
    // so each number x in [1..N] only affects numbers of the same parity.
    // Starting from all integers present, erasing x can only ever remove x itself;
    // all produced numbers already exist unless they were previously erased.
    //
    // The reachable erased sets inside one parity class are exactly the downward-closed
    // sets in the DAG with edges x -> x-2 and x -> x+K. For even K, this becomes a chain
    // in terms of t = (x-r)/2 with moves -1 and +K/2, hence if t is erased then t+1 must be erased.
    // Therefore in each parity class, the erased numbers form a suffix.
    //
    // Let cnt_odd = number of odd integers in [1..N], cnt_even = number of even integers in [1..N].
    // Number of choices = (cnt_odd + 1) * (cnt_even + 1).
    if (K % 2 == 0) {
        long long odd = (N + 1) / 2;
        long long even = N / 2;
        long long ans = (i128)((odd + 1) % M) * ((even + 1) % M) % M;
        cout << ans << '\n';
        return 0;
    }

    // For odd K, gcd(2, K) = 1, so all integers are in one component.
    // Consider directed edges x -> x-2 and x -> x+K.
    // Reachable erased sets are downward-closed sets in this DAG restricted to [1..N].
    //
    // Since gcd(2, K)=1, define rank modulo (K+2):
    // moving by -2 decreases rank by 2, moving by +K also decreases rank by 2 mod (K+2),
    // so along any operation rank changes consistently.
    //
    // More concretely, order numbers by residue class modulo (K+2):
    // every x in [1..N] belongs to exactly one chain:
    // x, x-(K+2), x-2(K+2), ...
    // and dependencies imply that if a number is erased, then all larger numbers in the same chain
    // must also be erased. Thus each chain contributes (len+1) choices independently.
    //
    // The chain heads are residues 1..K+2. For residue r, chain members in [1..N] are:
    // r, r+(K+2), r+2(K+2), ...
    // so len_r = floor((N-r)/(K+2)) + 1 if r<=N, else 0.
    //
    // Therefore answer = product over r=1..K+2 of (len_r + 1).
    //
    // Since lengths differ by at most 1, we can compute counts in O(1).
    long long L = K + 2;
    long long q = N / L;
    long long rem = N % L;
    // residues 1..rem have length q+1, residues rem+1..L have length q
    // contribution: (q+2)^rem * (q+1)^(L-rem)
    long long ans = mod_pow((q + 2) % M, rem, M);
    ans = (i128)ans * mod_pow((q + 1) % M, L - rem, M) % M;
    cout << ans << '\n';
    return 0;
}
